import{_ as t,o as i,c as n,a2 as r}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"CLI-Befehle","description":"","frontmatter":{},"headers":[],"relativePath":"de/cli/overview.md","filePath":"de/cli/overview.md","lastUpdated":1784903584000}'),o={name:"de/cli/overview.md"};function d(a,e,c,s,l,h){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="cli-befehle" tabindex="-1">CLI-Befehle <a class="header-anchor" href="#cli-befehle" aria-label="Permalink to &quot;CLI-Befehle&quot;">​</a></h1><h2 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h2><p>Die <code>swag2mcp</code>-CLI ist der einzige Einstiegspunkt für alle Operationen — von der Initialisierung eines Arbeitsbereichs und der Verwaltung von API-Spezifikationen bis zum Starten eines MCP-Servers für die LLM-Integration. Sie bietet <strong>13 Befehle</strong>, die den gesamten Lebenszyklus der Arbeit mit OpenAPI/Swagger/Postman-Spezifikationen abdecken.</p><h3 id="was-die-cli-lost" tabindex="-1">Was die CLI löst <a class="header-anchor" href="#was-die-cli-lost" aria-label="Permalink to &quot;Was die CLI löst&quot;">​</a></h3><ul><li><strong>Arbeitsbereichs-Lebenszyklus</strong> — erstellen (<code>init</code>), inspizieren (<code>info</code>, <code>ls</code>), bereinigen (<code>clean</code>), aktualisieren (<code>update</code>) und entfernen (<code>delete</code>) von Arbeitsbereichen und deren Inhalten</li><li><strong>Spec- und Collection-Verwaltung</strong> — hinzufügen (<code>add</code>), auflisten (<code>ls</code>) und löschen (<code>delete</code>) von API-Spezifikationen und deren Collections</li><li><strong>Ausführungsmodi</strong> — MCP-Server für LLM-Tool-Zugriff starten (<code>mcp</code>) oder den interaktiven TUI-Explorer starten (<code>run</code>)</li><li><strong>Diagnose</strong> — Konfiguration validieren (<code>validate</code>), Version anzeigen (<code>version</code>), Laufzeitinfo anzeigen (<code>info</code>)</li><li><strong>Backup &amp; Wiederherstellung</strong> — vollständiger Arbeitsbereichs-Roundtrip über ZIP (<code>export</code>, <code>import</code>)</li></ul><h3 id="wichtige-nuancen" tabindex="-1">Wichtige Nuancen <a class="header-anchor" href="#wichtige-nuancen" aria-label="Permalink to &quot;Wichtige Nuancen&quot;">​</a></h3><ul><li><strong>Pfadauflösung</strong> — Befehle, die <code>[path]</code> akzeptieren, erwarten ein <strong>Arbeitsbereichsverzeichnis</strong> (keinen Dateipfad). Auflösungsreihenfolge: expliziter <code>[path]</code> → aktuelles Verzeichnis (<code>./</code>) → <code>~/.swag2mcp/</code>. Die CLI hängt <code>swag2mcp.yaml</code> automatisch an. Geben Sie immer einen expliziten Pfad an, wenn Sie es als Dienst oder in der IDE-Konfiguration ausführen, um das Laden des falschen Arbeitsbereichs zu vermeiden.</li><li><strong>Spec vs Collection</strong> — eine <strong>Spec</strong> repräsentiert einen logischen API-Dienst (z. B. &quot;Open-Meteo API&quot;), während eine <strong>Collection</strong> eine einzelne OpenAPI/Swagger/Postman-Datei ist. Eine Spec kann mehrere Collections haben.</li><li><strong><code>--version</code></strong> wird sowohl als Flag (<code>swag2mcp --version</code>) als auch als Unterbefehl (<code>swag2mcp version</code>) unterstützt.</li><li><strong><code>add spec</code> / <code>add collection</code></strong> akzeptieren YAML-Eingabe über <code>--yaml</code> (Inline-Zeichenfolge oder <code>-</code> für stdin). Das Weiterleiten aus einer Datei oder einem Here-Doc vermeidet Shell-Anführungsprobleme mit Sonderzeichen.</li><li><strong><code>delete</code></strong> erfordert ein TTY (interaktives Terminal). Es gibt kein <code>--force</code>- oder <code>--yes</code>-Flag — es fordert immer zur Auswahl und Bestätigung auf.</li><li><strong><code>mcp</code></strong> ist der primäre Befehl für die LLM-Integration. Er unterstützt drei Transports: <code>stdio</code> (Standard), <code>sse</code> und <code>streamable-http</code>. Das Flag <code>--disable-llm-auth</code> (Standard: <code>true</code>) entfernt das <code>auth</code>-Tool aus der MCP-Tool-Liste und verhindert, dass der LLM Tokens sieht oder anfordert. Auth funktioniert weiterhin — Tokens werden über den Standard-Konfigurationsmechanismus bezogen, nicht über den LLM. Dieser Modus wird für die <strong>Produktion</strong> empfohlen (LLM hat niemals Zugriff auf Anmeldeinformationen). Für das <strong>Debuggen</strong> oder bei kurzlebigen Tokens setzen Sie <code>--disable-llm-auth=false</code>, damit der LLM frische Tokens über das <code>auth</code>-Tool anfordern kann.</li><li><strong><code>validate</code></strong> prüft YAML-Syntax, Konfigurationsstruktur, Spezifikationsdateiexistenz, URL-Erreichbarkeit, Spezifikationsformat (OpenAPI/Swagger/Postman), Auth-Einstellungen und HTTP-Client-Korrektheit. Es testet <strong>nicht</strong> Authentifizierungsendpunkte oder API-Endpunktverfügbarkeit.</li><li><strong><code>export</code> / <code>import</code></strong> bieten einen vollständigen Arbeitsbereichs-Roundtrip — Konfigurationsdatei, Spezifikationsdateien, Cache und Auth-Skripte sind alle im ZIP-Archiv enthalten.</li><li><strong><code>clean</code></strong> entfernt die Verzeichnisse <code>cache/</code> und <code>responses/</code>, behält aber <code>specs/</code> und <code>auth_scripts/</code>. Alte Antworten (&gt;48h) werden auch automatisch beim <code>mcp</code>-Start bereinigt.</li></ul><h2 id="befehle" tabindex="-1">Befehle <a class="header-anchor" href="#befehle" aria-label="Permalink to &quot;Befehle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Befehl</th><th>Beschreibung</th></tr></thead><tbody><tr><td><a href="/cli/init"><code>init</code></a></td><td>Arbeitsbereichsverzeichnis mit Standardkonfiguration initialisieren</td></tr><tr><td><a href="/cli/add"><code>add</code></a></td><td>Eine Spec oder Collection zur Konfiguration hinzufügen</td></tr><tr><td><a href="/cli/delete"><code>delete</code></a></td><td>Eine Spec oder Collection interaktiv löschen</td></tr><tr><td><a href="/cli/ls"><code>ls</code></a></td><td>Alle Specs und ihre Collections auflisten</td></tr><tr><td><a href="/cli/run"><code>run</code></a></td><td>Interaktiven TUI-API-Explorer starten</td></tr><tr><td><a href="/cli/validate"><code>validate</code></a></td><td>Konfiguration und Spezifikationsdateien validieren</td></tr><tr><td><a href="/cli/clean"><code>clean</code></a></td><td>Zwischengespeicherte Specs und Aufrufantworten löschen</td></tr><tr><td><a href="/cli/update"><code>update</code></a></td><td>Alle Specs neu validieren, neu cachen und neu indizieren</td></tr><tr><td><a href="/cli/mcp"><code>mcp</code></a></td><td>MCP-Server für LLM-Tool-Zugriff starten</td></tr><tr><td><a href="/cli/version"><code>version</code></a></td><td>swag2mcp-Version anzeigen</td></tr><tr><td><a href="/cli/info"><code>info</code></a></td><td>Detaillierte Konfigurations- und Laufzeitinformationen anzeigen</td></tr><tr><td><a href="/cli/import"><code>import</code></a></td><td>Spezifikationsdateien importieren oder Arbeitsbereich aus ZIP wiederherstellen</td></tr><tr><td><a href="/cli/export"><code>export</code></a></td><td>Arbeitsbereich als portables ZIP-Backup exportieren</td></tr></tbody></table><h2 id="globale-flags" tabindex="-1">Globale Flags <a class="header-anchor" href="#globale-flags" aria-label="Permalink to &quot;Globale Flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>--version</code></td><td>Version anzeigen (wie <code>version</code>-Unterbefehl)</td></tr><tr><td><code>--help</code></td><td>Hilfe für jeden Befehl anzeigen</td></tr></tbody></table>',11)])])}const f=t(o,[["render",d]]);export{g as __pageData,f as default};
